INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('9b603c4b-c8ad-45ba-bf30-a20df9b0de0c', '21feff02-016d-46e2-bb9d-c27495133b1b', '49. óra: Síkbeli alakzatok II.', 'Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "24788a6d-bbd5-4a39-9d7d-c468ef579ac1", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "5eecaf85-5ed8-4ae2-8030-e8206d997592", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "2052eecf-fb2c-4c1e-898a-c8819097d2f8", "text": "Négyzet", "isCorrect": true}, {"id": "82b2b40b-86bd-4a97-8185-05d3fbba909b", "text": "Rombusz", "isCorrect": false}, {"id": "0f2eee72-83ee-4e6e-83ce-3f76dd7d1f8a", "text": "Téglalap", "isCorrect": false}, {"id": "1b7bcebf-7167-4421-bdde-159973165326", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "d7ac9400-57d7-4e30-9d31-5924f97f9ee4", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "9b7b467b-9cb1-46da-81a2-2aeb2cb1f32f", "text": "Rombusz", "isCorrect": true}, {"id": "cacf6358-d2a0-40f2-a2d2-d8c8bdf58df2", "text": "Téglalap", "isCorrect": false}, {"id": "41540122-e1d9-43dc-8a55-e99ec47f0aef", "text": "Trapéz", "isCorrect": false}, {"id": "430ea892-3016-4de1-9b01-29f262a8df39", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "8e624bac-0d95-4b66-82db-d1403223898f", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "3ddb8d6b-86f9-4748-b7b7-9b347df4c4e1", "text": "Igaz", "isCorrect": true}, {"id": "43e8129f-aa62-4adf-920c-1a7d77e969b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f99f812b-f1c9-4799-a1d4-c0c7c7324e63", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "7048b0cc-c6b5-46de-ac8d-1503f0a592a3", "text": "Igaz", "isCorrect": true}, {"id": "e8260cc2-ffb1-42f5-b324-e0d6a9428cae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5cef51af-2887-450f-af4e-7938c5ca1e1b", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "a723b549-9f39-41eb-907b-1f35ed380a88", "text": "Igaz", "isCorrect": true}, {"id": "a90fd09d-28dd-4d7f-8ae5-ce33ac7a3414", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4c6dd5e6-2a4b-4a73-a2bb-9ce5c71c53aa", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
('0252d98e-bfc6-46ae-b257-adccb628fce7', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "74dac841-62f8-47d2-9725-4235cd18acda", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "7fff5c9f-d187-4e25-8c29-d0d5573b6f62", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "fc5d5a3c-b095-47cf-9885-1723ddeca669", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "5d53df06-03df-4412-8b0e-86bcc5ee3dba", "text": "Ha a területük 0", "isCorrect": false}, {"id": "e0745bb6-1ffd-4f3f-8f4e-a728f6786f37", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "6fd2b787-330a-475c-a66e-25fd9986e6a3", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "f874353d-f27d-4fc4-b6eb-4c21f1853416", "text": "Igaz", "isCorrect": true}, {"id": "8934069d-d35c-47f5-a5ea-967830477c98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b74033f-a2b3-4fb6-b184-bba2e6d28b4f", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "ef8b35cd-5485-446d-a4db-d223ef632629", "text": "Igaz", "isCorrect": true}, {"id": "8d2622c7-c246-4fa8-b46b-f38f2eba31ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7777793a-9f83-424d-9732-8dd7b57f5711", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "1e0374a2-4908-415b-ada0-c0d9c47ffeb7", "text": "Igaz", "isCorrect": false}, {"id": "6ed70263-e045-47c1-b40f-1276c4252a52", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "5da17ed8-a223-4634-8739-90abcaeef2ec", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "9cd5d6bf-b814-40be-982c-405c8173c312", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "fc3b5fec-27ee-4c33-bb02-1d29f3450485", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "9d527288-1daf-4f20-9e76-88413859e80b", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "daff86b6-5b57-4d32-822f-3edf63a5ba2b", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "f536e9ad-cdfe-4118-b36b-af8c14021091", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "4fda84de-d9d4-412a-9f38-beaa6ab14f2f", "text": "Igaz", "isCorrect": false}, {"id": "d65da16f-4cf3-46f3-b637-014d667d2735", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "861a0018-4eec-4002-8596-6284c7d0cff6", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "6eaccd7d-63cb-4db8-9dad-f212f111d6ae", "text": "Igaz", "isCorrect": true}, {"id": "eaff521c-f776-4b00-8ccd-efa436f6c041", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d0e6759b-e31b-4f08-97e9-5bbcf1808085', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "5ab23343-47bd-4bfc-8f76-0ebe97c07587", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "60437d0b-8609-430a-b907-7533abbbbb2a", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "c92672c8-9ef5-4e06-86b6-9d8eff649c9b", "text": "d = r / 2", "isCorrect": false}, {"id": "451b4d4a-841f-4e5a-91d6-6fbc66e20a2d", "text": "d = r + 5", "isCorrect": false}, {"id": "a9b27645-2479-473e-8045-6c1dcb3be263", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "873264f4-5eb4-4722-ad6e-83896947bc79", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "1693773a-c058-4347-8b0f-869e154c92c7", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "fcb2dc22-fd1e-44b3-9355-520210facd8c", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "42c11049-050e-4a8a-85f5-5d1d6a18888e", "text": "Igaz", "isCorrect": true}, {"id": "c48557d0-c9a9-4ade-b588-7c27b59219ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aa211d84-731b-4dd2-8d36-76454d7aaea1", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "284bd551-db90-4a47-a7eb-d6b5a4a20659", "text": "Az átmérő", "isCorrect": true}, {"id": "7d86e7fb-c95b-44fb-a699-bdfdd8ee7c5f", "text": "A sugár", "isCorrect": false}, {"id": "873adf4f-4086-490b-af65-c9ab56b69bec", "text": "A körív", "isCorrect": false}, {"id": "912927f5-0704-403f-a722-e43a992472e0", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "eb5a6f4f-7e6d-462a-8e90-57e73cd6b3f9", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "e801d351-0c1b-4920-a29f-86fb8e454047", "text": "Igaz", "isCorrect": true}, {"id": "83cf4359-ddff-4b88-8ad0-03217a49250a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "78d3d65f-01d2-4783-aa9d-36e2b72071e5", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "81563d5b-9f0c-4c22-af26-56c65a1c1a59", "text": "Igaz", "isCorrect": true}, {"id": "c84e7b48-4f43-4380-924b-8386318ae8b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('c13fe143-e6d2-431d-b66a-8259e5413dd4', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "ccb9fc12-9009-4ca5-9deb-fc3abb9899c2", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "80b6ecde-cbd6-40d1-a9b4-b7ac0615b0c1", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "61ccbcf5-55bc-44fc-beb3-53f769a83997", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "17fc78d4-b06d-48b4-9a1f-adff71a973ba", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "7a75e4ec-aed6-4198-81c8-71d19a24b8f3", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "cbe78bec-3139-4450-abb8-489263daec70", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "8e7b1882-c05e-47b7-b1a3-f128dd7af66e", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "b750c14c-d391-483f-bd6d-5a2b366c1f3d", "text": "Igaz", "isCorrect": true}, {"id": "7742d34e-cb07-4fb6-959d-e593458223fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fea83bb0-c4ec-4402-99af-28ba43778100", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "268512ba-f5d3-4276-9887-976f4af1fd9a", "text": "Igaz", "isCorrect": true}, {"id": "64f1ef4c-00c9-47d3-bcf1-5e4f97e6b2d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4479f73-6d95-44e5-8a75-e1b72b9768aa", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "0ebb82a2-2b7b-49ce-8c10-18e36bd0ce7e", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "e077534a-d4db-42c8-ba50-d43fcfbdcc2b", "text": "Igaz", "isCorrect": true}, {"id": "608e35e4-430e-43a8-ba30-4746d839cb74", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e605dc37-e127-43f7-b928-b2e917593498", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "486db3a7-0176-4a31-a116-29a371c2732b", "text": "Igaz", "isCorrect": true}, {"id": "a3e3c5a9-2689-4989-8e75-812976e2f6f3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('edbe855d-033c-425a-a806-9db62e0c3d80', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "617357c7-e1a7-4690-8418-1f96e0f9a7d9", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "ca212ad4-bf49-4a3c-b379-5f607fb26829", "text": "Körzőt", "isCorrect": true}, {"id": "4b5a3e44-1977-4e7a-acc0-070f11bbe74b", "text": "Szögmérőt", "isCorrect": false}, {"id": "cd6457e1-b030-4989-9c2f-accf72e60bb7", "text": "Radírt", "isCorrect": false}, {"id": "8abb6fee-a951-4138-b8f9-d67602784b19", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "7749eba6-b0ab-425e-be8f-b86f7fab245f", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "9b6e307d-24f8-43a2-9646-edf4f4041824", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "a894c8c6-a900-456a-8341-61533f3f5e53", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "ac15a179-9892-4e34-aac3-35ec8420a793", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "c36892b5-90c0-403c-b3b8-f7c2b1e30af1", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "1f5d4332-8d6f-4d83-919a-a57ebf2e913d", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "16ed790e-1f37-4e03-8c05-25f48d9278fd", "text": "Igaz", "isCorrect": true}, {"id": "4a4264f2-0a3f-4ee2-8116-5adf380d85a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a5fa109-70f8-46a5-ba02-64e42de34bd4", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "cf1ba6f6-471a-40db-a975-a433af461359", "text": "Igaz", "isCorrect": true}, {"id": "65098ea7-72be-462c-8472-22fc04f5659b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8908e197-4e0c-45e0-9539-1e098d832611", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "5891ba1a-f81c-451e-91ac-7ffe3565e4c6", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "2eae15b4-d6d3-4648-a4f5-0eaf89dd47cd", "text": "Igaz", "isCorrect": true}, {"id": "2e81d4ed-a105-41bf-8e65-3472439e6f70", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b9db03be-18cf-433a-a9b5-20223465785f", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "9e681939-656d-4f4e-8edf-d22783e62c45", "text": "Igaz", "isCorrect": true}, {"id": "a198df82-c3f5-4238-bc29-f6aab1e1b62d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());